insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá suspender, por tempo não inferior a 2 nem superior a 6 anos, a execução das penas de reclusão e de detenção que não excedam 2 anos, ou, por tempo não inferior a 1 nem superior a 3 anos, a execução da pena de prisão simples, desde que o sentenciado não haja sofrido condenação irrecorrível por outro crime a pena privativa de liberdade (salvo o parágrafo único do art. 46 do Código Penal) e que seus antecedentes, personalidade, motivos e circunstâncias autorizem a presunção de que não tornará a delinquir. Processado o beneficiário por outro crime ou contravenção, o prazo da suspensão considera-se prorrogado até o julgamento definitivo.', '["Sursis: reclusão ou detenção até 2 anos, suspensa por 2 a 6 anos.","Prisão simples: suspensão por 1 a 3 anos.","Requisitos: sem condenação irrecorrível anterior a pena de prisão; presunção de que não voltará a delinquir.","Processado por novo crime: prazo prorrogado até o julgamento."]'::jsonb, '["Hoje a suspensão condicional da pena está nos arts. 77 e seguintes do Código Penal e na Lei de Execução Penal; prevalecem estas regras."]'::jsonb, 'Condenado a 1 ano de detenção, sem antecedentes, pode ter a pena suspensa por 2 a 6 anos.', '["Assertiva que aplica a suspensão a pena de reclusão de 3 anos erra: o limite no texto é de 2 anos."]'::jsonb, '[{"termo":"Sursis","significado":"Suspensão condicional da execução da pena."}]'::jsonb, '["Art. 697","Art. 698"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-696'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz ou tribunal, na decisão que aplicar pena privativa da liberdade não superior a 2 anos, deverá pronunciar-se, motivadamente, sobre a suspensão condicional, quer a conceda quer a denegue.', '["Pena até 2 anos: o juiz deve se manifestar sobre a suspensão condicional.","Concedendo ou negando, com motivação."]'::jsonb, '["Dever de pronunciamento, e não de concessão automática."]'::jsonb, 'Na sentença que fixa 1 ano de detenção, o juiz decide expressamente sobre o sursis.', '["Assertiva que dispensa o juiz de se manifestar sobre o sursis quando o negar erra: deve fundamentar."]'::jsonb, '[]'::jsonb, '["Art. 696"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-697'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concedida a suspensão, o juiz especificará as condições a que fica sujeito o condenado, pelo prazo previsto, começando este a correr da audiência em que se der conhecimento da sentença ao beneficiário e lhe for entregue documento similar ao do art. 724. As condições serão adequadas ao delito e à personalidade do condenado. Poderão ser impostas, além das do art. 767, frequentar curso de habilitação profissional ou de instrução escolar; prestar serviços em favor da comunidade; atender aos encargos de família; e submeter-se a tratamento de desintoxicação. O juiz poderá fixar, a qualquer tempo, de ofício ou a requerimento do Ministério Público, outras condições, desde que as circunstâncias o aconselhem.', '["Juiz especifica as condições; o prazo corre da audiência.","Condições adequadas ao delito e à personalidade.","Exemplos: curso, serviços à comunidade, encargos de família, desintoxicação.","Condições adicionais a qualquer tempo, de ofício ou a pedido do MP."]'::jsonb, '["O prazo conta da audiência de advertência."]'::jsonb, 'O juiz impõe curso profissionalizante e comparecimento periódico como condições do sursis.', '["Assertiva que fixa condições imutáveis na sentença erra: podem ser acrescidas a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 703","Art. 724"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-698'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

