select u.id, u.content_sha256, 'No caso de condenação pelo Tribunal do Júri, a suspensão condicional da pena competirá ao seu presidente.', '["Condenação pelo Júri: o presidente decide a suspensão condicional."]'::jsonb, '["O presidente do Júri é o juiz togado."]'::jsonb, 'O juiz presidente decide sobre o sursis da condenação do Júri.', '["Assertiva que atribui o sursis do Júri aos jurados erra: compete ao presidente."]'::jsonb, '[]'::jsonb, '["Art. 492"]'::jsonb, 'under_review', 'claude'
