insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, ao conceder a suspensão, fixará, tendo em conta as condições econômicas ou profissionais do réu, o prazo para o pagamento, integral ou em prestações, das custas do processo e taxa penitenciária.', '["Juiz fixa o prazo de pagamento das custas e da taxa penitenciária.","Considera as condições econômicas ou profissionais do réu."]'::jsonb, '["Pode ser em prestações."]'::jsonb, 'O juiz permite que o condenado pague as custas em parcelas.', '["Assertiva que dispensa o pagamento das custas por quem tem sursis erra."]'::jsonb, '[]'::jsonb, '["Art. 700"]'::jsonb, 'under_review', 'claude'
