insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz que conceder a suspensão lerá ao réu, em audiência, a sentença respectiva, e o advertirá das consequências de nova infração penal e da transgressão das obrigações impostas.', '["Audiência de advertência: leitura da sentença ao réu.","Advertência sobre nova infração e descumprimento das obrigações."]'::jsonb, '["Marco inicial do período de prova (art. 698)."]'::jsonb, 'Na audiência, o juiz lê a sentença e adverte o réu sobre as consequências de nova infração.', '["Assertiva que dispensa a audiência de advertência erra."]'::jsonb, '[]'::jsonb, '["Art. 705"]'::jsonb, 'under_review', 'claude'
