insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando for concedida a suspensão pela superior instância, a esta caberá estabelecer-lhe as condições, podendo a audiência ser presidida por qualquer membro do tribunal ou câmara, pelo juiz do processo ou por outro designado pelo presidente do tribunal ou câmara.', '["Sursis concedido pelo tribunal: ele fixa as condições.","Audiência presidida por membro do tribunal, juiz do processo ou outro designado."]'::jsonb, '["Competência do tribunal para fixar as condições."]'::jsonb, 'O tribunal concede o sursis e define as condições; o juiz do processo preside a audiência.', '["Assertiva que deixa ao juiz de primeira instância definir as condições do sursis concedido pelo tribunal erra."]'::jsonb, '[]'::jsonb, '["Art. 703"]'::jsonb, 'under_review', 'claude'
