select u.id, u.content_sha256, 'Se, intimado pessoalmente ou por edital com prazo de 20 dias, o réu não comparecer à audiência a que se refere o art. 703, a suspensão ficará sem efeito e será executada imediatamente a pena, salvo prova de justo impedimento, caso em que será marcada nova audiência.', '["Réu não comparece à audiência, intimado pessoalmente ou por edital de 20 dias: suspensão sem efeito.","Pena executada imediatamente.","Exceção: justo impedimento, com nova audiência."]'::jsonb, '["Edital de 20 dias."]'::jsonb, 'O réu falta à audiência sem justificativa: o sursis perde o efeito.', '["Assertiva que mantém o sursis diante da ausência injustificada à audiência erra."]'::jsonb, '[]'::jsonb, '["Art. 703"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-705'
