select u.id, u.content_sha256, 'Expirado o prazo de suspensão ou a prorrogação, sem que tenha ocorrido motivo de revogação, a pena privativa de liberdade será declarada extinta. O juiz, quando julgar necessário, requisitará, antes do julgamento, nova folha de antecedentes do beneficiário.', '["Fim do período de prova sem revogação: pena declarada extinta.","Juiz pode requisitar nova folha de antecedentes."]'::jsonb, '["Cumprido o período de prova, a pena se extingue."]'::jsonb, 'Terminado o prazo do sursis sem motivo de revogação, o juiz declara extinta a pena.', '["Assertiva que obriga o cumprimento da pena após o fim do período de prova sem revogação erra."]'::jsonb, '[]'::jsonb, '["Art. 696"]'::jsonb, 'under_review', 'claude'
