insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A condenação será inscrita, com a nota de suspensão, em livros especiais do Instituto de Identificação e Estatística, ou repartição congênere, averbando-se, mediante comunicação do juiz ou do tribunal, a revogação da suspensão ou a extinção da pena. Nos lugares onde não houver o Instituto, o registro e a averbação serão feitos em livro próprio no juízo ou no tribunal. O registro será secreto, salvo para efeito de informações requisitadas por autoridade judiciária, no caso de novo processo. Não se aplica o sigilo quando houver sido imposta ou resultar de condenação pena acessória consistente em interdição de direitos.', '["Condenação inscrita com nota de suspensão.","Averbação da revogação ou da extinção da pena.","Sem Instituto: livro próprio no juízo.","Registro secreto, exceto para autoridade judiciária em novo processo.","Sigilo afastado se houver interdição de direitos."]'::jsonb, '["Registro sigiloso."]'::jsonb, 'O registro do sursis só é revelado a autoridade judiciária em novo processo.', '["Assertiva que torna público o registro do sursis erra."]'::jsonb, '[]'::jsonb, '["Art. 694"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-709'
