insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O livramento condicional poderá ser concedido ao condenado a pena privativa da liberdade igual ou superior a 2 anos, desde que se verifiquem as condições seguintes: cumprimento de mais da metade da pena, ou mais de três quartos, se reincidente; ausência ou cessação de periculosidade; bom comportamento durante a vida carcerária; aptidão para prover à própria subsistência mediante trabalho honesto; e reparação do dano causado pela infração, salvo impossibilidade de fazê-lo.', '["Pena igual ou superior a 2 anos.","Cumprimento de mais da metade (mais de três quartos se reincidente).","Ausência de periculosidade e bom comportamento.","Aptidão para o trabalho honesto.","Reparação do dano, salvo impossibilidade."]'::jsonb, '["Hoje o livramento condicional é regulado pelo art. 83 do Código Penal (frações atuais)."]'::jsonb, 'O condenado que cumpriu a fração exigida, com bom comportamento, pede o livramento condicional.', '["Assertiva que dispensa a reparação do dano, mesmo havendo possibilidade de repará-lo, erra."]'::jsonb, '[{"termo":"Livramento condicional","significado":"Liberdade antecipada, sob condições, no final da pena."}]'::jsonb, '["Art. 83 do Código Penal"]'::jsonb, 'under_review', 'claude'
