select u.id, u.content_sha256, 'O livramento condicional poderá ser concedido mediante requerimento do sentenciado, de seu cônjuge ou de parente em linha reta, ou por proposta do diretor do estabelecimento penal, ou por iniciativa do Conselho Penitenciário.', '["Legitimados: sentenciado, cônjuge, parente em linha reta, diretor do estabelecimento ou Conselho Penitenciário."]'::jsonb, '["Vários legitimados."]'::jsonb, 'O diretor do presídio propõe o livramento condicional de um preso.', '["Assertiva que restringe o pedido ao próprio sentenciado erra."]'::jsonb, '[]'::jsonb, '["Art. 713"]'::jsonb, 'under_review', 'claude'
