insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As condições de admissibilidade, conveniência e oportunidade da concessão do livramento serão verificadas pelo Conselho Penitenciário, a cujo parecer não ficará, entretanto, adstrito o juiz.', '["Conselho Penitenciário verifica as condições.","Parecer não vincula o juiz."]'::jsonb, '["Parecer opinativo."]'::jsonb, 'O juiz concede o livramento mesmo contra o parecer do Conselho, fundamentando.', '["Assertiva que vincula o juiz ao parecer do Conselho Penitenciário erra."]'::jsonb, '[]'::jsonb, '["Art. 714"]'::jsonb, 'under_review', 'claude'
