insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O diretor do estabelecimento penal remeterá ao Conselho Penitenciário minucioso relatório sobre o caráter do sentenciado, revelado pelos seus antecedentes e conduta na prisão; o procedimento do liberando na prisão, sua aplicação ao trabalho e seu trato com companheiros e funcionários; suas relações com a família e estranhos; seu grau de instrução e aptidão profissional; e sua situação financeira e propósitos quanto ao futuro meio de vida. O relatório será remetido em quinze dias, com o prontuário do sentenciado; na falta, o Conselho opinará livremente.', '["Relatório do diretor sobre caráter, conduta, relações, instrução e situação financeira.","Prazo de quinze dias.","Sem relatório, o Conselho opina livremente e comunica a omissão."]'::jsonb, '["Prazo de quinze dias para o relatório."]'::jsonb, 'O diretor envia em quinze dias o relatório sobre o comportamento do preso.', '["Assertiva que fixa em cinco dias o prazo do relatório do diretor erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 713"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-714'
