insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se tiver sido imposta medida de segurança detentiva, o livramento não poderá ser concedido sem que se verifique, mediante exame das condições do sentenciado, a cessação da periculosidade. Consistindo a medida de segurança em internação em casa de custódia e tratamento, proceder-se-á a exame mental do sentenciado.', '["Medida de segurança detentiva: livramento só com cessação da periculosidade.","Internação em casa de custódia: exame mental."]'::jsonb, '["Exame da periculosidade."]'::jsonb, 'Antes do livramento, faz-se exame mental do sentenciado internado.', '["Assertiva que concede o livramento sem verificar a cessação da periculosidade erra."]'::jsonb, '[]'::jsonb, '["Art. 710"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-715'
