insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A petição ou a proposta de livramento será remetida ao juiz ou ao tribunal por ofício do presidente do Conselho Penitenciário, com a cópia do respectivo parecer e do relatório do diretor da prisão. Para emitir parecer, o Conselho poderá determinar diligências e requisitar os autos do processo. O juiz ou o tribunal mandará juntar a petição ou a proposta aos autos e proferirá sua decisão, previamente ouvido o Ministério Público.', '["Petição enviada pelo presidente do Conselho, com parecer e relatório.","Conselho pode determinar diligências.","Decisão após ouvir o MP."]'::jsonb, '["Oitiva prévia do MP."]'::jsonb, 'O juiz decide o livramento depois de ouvir o Ministério Público.', '["Assertiva que dispensa a oitiva do MP antes da decisão sobre o livramento erra."]'::jsonb, '[]'::jsonb, '["Art. 714"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-716'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ausência da condição prevista no art. 710, I (cumprimento da fração da pena), o requerimento será liminarmente indeferido.', '["Sem o tempo mínimo de pena cumprida, indeferimento liminar."]'::jsonb, '["Requisito objetivo."]'::jsonb, 'O preso pede o livramento sem ter cumprido a fração exigida: indeferimento imediato.', '["Assertiva que processa o pedido sem a fração mínima cumprida erra."]'::jsonb, '[]'::jsonb, '["Art. 710"]'::jsonb, 'under_review', 'claude'
