on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deferido o pedido, o juiz, ao especificar as condições a que ficará subordinado o livramento, atenderá ao disposto no art. 698, §§ 1º, 2º e 5º. Se for permitido ao liberado residir fora da jurisdição do juiz da execução, remeter-se-á cópia da sentença do livramento à autoridade judiciária do lugar para onde ele se transferir e à entidade de observação cautelar e proteção. O liberado será advertido da obrigação de apresentar-se imediatamente à autoridade judiciária e à entidade de observação cautelar e proteção.', '["Condições segundo o art. 698, §§ 1º, 2º e 5º.","Residência fora da jurisdição: cópia da sentença à autoridade do novo local.","Advertência da obrigação de apresentação imediata."]'::jsonb, '["Comunicação ao novo local de residência."]'::jsonb, 'O liberado muda de comarca, e a sentença é enviada ao juízo local.', '["Assertiva que dispensa a comunicação ao juízo do novo local de residência erra."]'::jsonb, '[]'::jsonb, '["Art. 698"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-718'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O livramento ficará também subordinado à obrigação de pagamento das custas do processo e da taxa penitenciária, salvo caso de insolvência comprovada. O juiz poderá fixar o prazo para o pagamento integral ou em prestações, tendo em consideração as condições econômicas ou profissionais do liberado.', '["Livramento subordinado ao pagamento das custas e da taxa penitenciária.","Exceção: insolvência comprovada.","Prazo e parcelamento fixados pelo juiz."]'::jsonb, '["Insolvência comprovada afasta a obrigação."]'::jsonb, 'O liberado insolvente comprovado fica dispensado das custas.', '["Assertiva que obriga o pagamento das custas mesmo na insolvência comprovada erra."]'::jsonb, '[]'::jsonb, '["Art. 701"]'::jsonb, 'under_review', 'claude'
