insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A forma de pagamento da multa, ainda não paga pelo liberando, será determinada de acordo com o disposto no art. 688.', '["Pagamento da multa pendente segue o art. 688."]'::jsonb, '["Remissão ao art. 688."]'::jsonb, 'A multa pendente do liberando segue o rito de cobrança do art. 688.', '["Assertiva que cria forma própria de pagamento da multa no livramento erra: aplica-se o art. 688."]'::jsonb, '[]'::jsonb, '["Art. 688"]'::jsonb, 'under_review', 'claude'
