insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reformada a sentença denegatória do livramento, os autos baixarão ao juiz da primeira instância, a fim de que determine as condições que devam ser impostas ao liberando.', '["Reformada a negativa: autos voltam à primeira instância.","O juiz fixa as condições do livramento."]'::jsonb, '["O juiz de primeiro grau fixa as condições."]'::jsonb, 'O tribunal reforma a negativa, e o juiz da execução define as condições.', '["Assertiva que atribui ao tribunal a fixação das condições após reformar a negativa erra."]'::jsonb, '[]'::jsonb, '["Art. 718"]'::jsonb, 'under_review', 'claude'
