insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concedido o livramento, será expedida carta de guia, com a cópia integral da sentença em duas vias, remetendo-se uma ao diretor do estabelecimento penal e outra ao presidente do Conselho Penitenciário.', '["Carta de guia com cópia integral da sentença em duas vias.","Uma ao diretor e outra ao presidente do Conselho Penitenciário."]'::jsonb, '["Duas vias."]'::jsonb, 'A carta de guia do livramento segue ao diretor e ao Conselho Penitenciário.', '["Assertiva que dispensa a carta de guia no livramento erra."]'::jsonb, '[]'::jsonb, '["Art. 676"]'::jsonb, 'under_review', 'claude'
