insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cerimônia do livramento condicional será realizada solenemente, em dia marcado pela autoridade que deva presidi-la, observando-se que a sentença será lida ao liberando, na presença dos demais presos, salvo motivo relevante, pelo presidente do Conselho Penitenciário, seu representante ou, na falta, pela autoridade judiciária local; o diretor do estabelecimento chamará a atenção do liberando para as condições impostas; e o preso declarará se aceita as condições. De tudo se lavrará termo em livro próprio, subscrito por quem presidir a cerimônia e pelo liberando, ou alguém a seu rogo, enviando-se cópia ao juiz do processo.', '["Cerimônia solene, em dia marcado.","Leitura da sentença na presença dos demais presos.","Diretor chama a atenção para as condições.","O preso declara se aceita as condições.","Termo em livro próprio, com cópia ao juiz."]'::jsonb, '["O liberando precisa aceitar as condições."]'::jsonb, 'Na cerimônia, o preso declara aceitar as condições do livramento.', '["Assertiva que dispensa a aceitação das condições pelo liberando erra."]'::jsonb, '[]'::jsonb, '["Art. 724"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-723'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao sair da prisão, o liberado receberá, além do saldo do seu pecúlio e do que lhe pertencer, uma caderneta que exibirá à autoridade judiciária ou administrativa sempre que lhe for exigido, contendo a reprodução da ficha de identidade ou o retrato do liberado, sua qualificação e sinais; o texto impresso dos artigos do capítulo; as condições impostas; e a pena acessória a que esteja sujeito. Na falta de caderneta, será entregue um salvo-conduto com as condições e a pena acessória. Na caderneta e no salvo-conduto deve haver espaço para consignar o cumprimento das condições do art. 718.', '["Liberado recebe pecúlio e caderneta.","Caderneta: identificação, texto dos artigos, condições e pena acessória.","Na falta: salvo-conduto.","Espaço para anotar o cumprimento das condições."]'::jsonb, '["Caderneta ou salvo-conduto do liberado."]'::jsonb, 'Ao sair, o liberado recebe a caderneta com as condições do livramento.', '["Assertiva que dispensa a entrega de caderneta ou salvo-conduto ao liberado erra."]'::jsonb, '[]'::jsonb, '["Art. 718","Art. 723"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-724'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A observação cautelar e proteção realizadas por serviço social penitenciário, patronato, conselho de comunidade ou entidades similares terá a finalidade de fazer observar o cumprimento da pena acessória, bem como das condições especificadas na sentença concessiva do benefício, e de proteger o beneficiário, orientando-o na execução de suas obrigações e auxiliando-o na obtenção de atividade laborativa. As entidades apresentarão relatório ao Conselho Penitenciário, para efeito da representação prevista nos arts. 730 e 731.', '["Observação cautelar: fiscalizar o cumprimento da pena acessória e das condições.","Proteger e orientar o beneficiário, inclusive na obtenção de trabalho.","Relatórios ao Conselho Penitenciário."]'::jsonb, '["Fiscalização e proteção ao mesmo tempo."]'::jsonb, 'O patronato acompanha o liberado e o ajuda a conseguir emprego.', '["Assertiva que restringe a observação cautelar à fiscalização, sem proteção ao beneficiário, erra."]'::jsonb, '[]'::jsonb, '["Art. 730"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-725'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogar-se-á o livramento condicional se o liberado vier, por crime ou contravenção, a ser condenado por sentença irrecorrível a pena privativa de liberdade.', '["Revogação obrigatória: condenação irrecorrível a pena privativa de liberdade, por crime ou contravenção."]'::jsonb, '["Revogação obrigatória."]'::jsonb, 'O liberado é condenado definitivamente a prisão por novo crime: o livramento é revogado.', '["Assertiva que torna facultativa a revogação por condenação irrecorrível a pena de prisão erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 727"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-726'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz pode, também, revogar o livramento se o liberado deixar de cumprir qualquer das obrigações constantes da sentença, de observar proibições inerentes à pena acessória ou for irrecorrivelmente condenado, por crime, à pena que não seja privativa da liberdade. Se o juiz não revogar o livramento, deverá advertir o liberado ou exacerbar as condições.', '["Revogação facultativa: descumprimento das obrigações, violação de proibições da pena acessória, condenação a pena não privativa de liberdade.","Sem revogação: advertência ou exacerbação das condições."]'::jsonb, '["Facultativa (''pode'')."]'::jsonb, 'O liberado descumpre uma condição, e o juiz opta por advertência em vez de revogar.', '["Assertiva que torna obrigatória a revogação por descumprimento de condição erra: é facultativa."]'::jsonb, '[]'::jsonb, '["Art. 726"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-727'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a revogação for motivada por infração penal anterior à vigência do livramento, computar-se-á no tempo da pena o período em que esteve solto o liberado, sendo permitida, para a concessão de novo livramento, a soma do tempo das duas penas.', '["Revogação por infração anterior ao livramento: o tempo solto é computado.","Soma das penas para novo livramento."]'::jsonb, '["Consequência mais branda que a do art. 729."]'::jsonb, 'A revogação decorre de crime anterior ao livramento: o tempo em liberdade conta como pena cumprida.', '["Assertiva que desconta o tempo solto quando a infração é anterior ao livramento erra: ele é computado."]'::jsonb, '[]'::jsonb, '["Art. 729"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-728'
