select u.id, u.content_sha256, 'No caso de revogação por outro motivo, não se computará na pena o tempo em que esteve solto o liberado, e tampouco se concederá, em relação à mesma pena, novo livramento.', '["Revogação por outro motivo: o tempo solto não é computado.","Não há novo livramento em relação à mesma pena."]'::jsonb, '["Consequência mais grave; compare com o art. 728."]'::jsonb, 'O livramento é revogado por descumprimento de condição: o tempo solto não conta.', '["Assertiva que permite novo livramento da mesma pena após revogação por descumprimento erra."]'::jsonb, '[]'::jsonb, '["Art. 728"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-729'
