insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revogação do livramento será decretada mediante representação do Conselho Penitenciário, ou a requerimento do Ministério Público, ou de ofício, pelo juiz, que, antes, ouvirá o liberado, podendo ordenar diligências e permitir a produção de prova, no prazo de cinco dias.', '["Revogação por representação do Conselho, requerimento do MP ou de ofício.","Antes, o juiz ouve o liberado.","Prova e diligências em cinco dias."]'::jsonb, '["Contraditório prévio: oitiva do liberado."]'::jsonb, 'O MP requer a revogação, e o juiz ouve o liberado antes de decidir.', '["Assertiva que dispensa a oitiva do liberado antes da revogação erra."]'::jsonb, '[]'::jsonb, '["Art. 726","Art. 727"]'::jsonb, 'under_review', 'claude'
