insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, a requerimento do Ministério Público, ou mediante representação do Conselho Penitenciário, poderá modificar as condições ou normas de conduta especificadas na sentença, devendo a respectiva decisão ser lida ao liberado por uma das autoridades ou por um dos funcionários indicados no inciso I do art. 723, observado o disposto nos incisos II e III do mesmo artigo.', '["Modificação das condições de ofício, a pedido do MP ou por representação do Conselho.","Decisão lida ao liberado, observado o art. 723."]'::jsonb, '["Leitura da decisão ao liberado."]'::jsonb, 'O juiz acrescenta uma condição e a decisão é lida ao liberado.', '["Assertiva que dispensa a leitura da decisão que modifica as condições ao liberado erra."]'::jsonb, '[]'::jsonb, '["Art. 723"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-731'
