insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticada pelo liberado nova infração, o juiz ou o tribunal poderá ordenar a sua prisão, ouvido o Conselho Penitenciário, suspendendo o curso do livramento condicional, cuja revogação ficará, entretanto, dependendo da decisão final no novo processo.', '["Nova infração: o juiz pode ordenar a prisão do liberado.","Suspende o curso do livramento.","Revogação depende da decisão final no novo processo."]'::jsonb, '["Suspensão cautelar, e não revogação imediata."]'::jsonb, 'O liberado é acusado de novo crime, e o livramento fica suspenso até o julgamento.', '["Assertiva que revoga imediatamente o livramento pela simples acusação de nova infração erra."]'::jsonb, '[]'::jsonb, '["Art. 733"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-732'
