insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, ou a requerimento do interessado, do Ministério Público, ou do Conselho Penitenciário, julgará extinta a pena privativa de liberdade, se expirar o prazo do livramento sem revogação, ou, na hipótese do artigo anterior, for o liberado absolvido por sentença irrecorrível.', '["Pena extinta se expirar o prazo do livramento sem revogação.","Ou se o liberado for absolvido da nova infração por sentença irrecorrível."]'::jsonb, '["Extinção da pena."]'::jsonb, 'Findo o período do livramento sem revogação, a pena é declarada extinta.', '["Assertiva que mantém a pena após o fim do livramento sem revogação erra."]'::jsonb, '[]'::jsonb, '["Art. 732"]'::jsonb, 'under_review', 'claude'
