insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A graça poderá ser provocada por petição do condenado, de qualquer pessoa do povo, do Conselho Penitenciário ou do Ministério Público, ressalvada, entretanto, ao Presidente da República, a faculdade de concedê-la espontaneamente.', '["Provocada por petição do condenado, de qualquer pessoa, do Conselho ou do MP.","O Presidente pode concedê-la espontaneamente."]'::jsonb, '["A graça é individual; o indulto é coletivo."]'::jsonb, 'Familiares peticionam a graça em favor do condenado.', '["Assertiva que restringe a provocação da graça ao próprio condenado erra."]'::jsonb, '[{"termo":"Graça","significado":"Clemência individual concedida pelo Presidente da República."}]'::jsonb, '["Art. 735"]'::jsonb, 'under_review', 'claude'
