select u.id, u.content_sha256, 'A petição de graça, acompanhada dos documentos com que o impetrante a instruir, será remetida ao ministro da Justiça por intermédio do Conselho Penitenciário.', '["Petição de graça vai ao ministro da Justiça por meio do Conselho Penitenciário."]'::jsonb, '["Trâmite pelo Conselho Penitenciário."]'::jsonb, 'O Conselho Penitenciário encaminha ao ministro da Justiça a petição de graça.', '["Assertiva que envia a petição diretamente ao Presidente da República sem passar pelo Conselho erra."]'::jsonb, '[]'::jsonb, '["Art. 734"]'::jsonb, 'under_review', 'claude'
