select u.id, u.content_sha256, 'O Conselho Penitenciário, à vista dos autos do processo, e depois de ouvir o diretor do estabelecimento penal a que estiver recolhido o condenado, fará, em relatório, a narração do fato criminoso, examinará as provas, mencionará qualquer formalidade ou circunstância omitida na petição e exporá os antecedentes do condenado e seu procedimento depois do ato delituoso, opinando sobre o mérito do pedido.', '["Conselho ouve o diretor do estabelecimento.","Relatório: fato criminoso, provas, omissões da petição, antecedentes e conduta posterior.","Opina sobre o mérito."]'::jsonb, '["Relatório do Conselho Penitenciário."]'::jsonb, 'O Conselho elabora relatório e opina sobre o pedido de graça.', '["Assertiva que dispensa o relatório do Conselho Penitenciário erra."]'::jsonb, '[]'::jsonb, '["Art. 735"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-736'
