select u.id, u.content_sha256, 'Processada no Ministério da Justiça, com os documentos e o relatório do Conselho Penitenciário, a petição subirá a despacho do Presidente da República, a quem serão presentes os autos do processo ou a certidão de qualquer de suas peças, se ele o determinar.', '["Petição processada no Ministério da Justiça.","Segue ao despacho do Presidente da República.","Autos ou certidões se ele determinar."]'::jsonb, '["Decisão final do Presidente da República."]'::jsonb, 'O Ministério da Justiça encaminha a petição ao Presidente para despacho.', '["Assertiva que atribui ao ministro da Justiça a decisão final da graça erra."]'::jsonb, '[]'::jsonb, '["Art. 736"]'::jsonb, 'under_review', 'claude'
