select u.id, u.content_sha256, 'Concedida a graça e junta aos autos cópia do decreto, o juiz declarará extinta a pena ou penas, ou ajustará a execução aos termos do decreto, no caso de redução ou comutação de pena.', '["Graça concedida: o juiz declara extinta a pena ou ajusta a execução.","Redução ou comutação: execução ajustada ao decreto."]'::jsonb, '["Extinção ou ajuste conforme o decreto."]'::jsonb, 'Com a graça, o juiz declara extinta a pena.', '["Assertiva que mantém a execução intacta após a graça erra."]'::jsonb, '[{"termo":"Comutação","significado":"Substituição da pena por outra mais branda."}]'::jsonb, '["Art. 734"]'::jsonb, 'under_review', 'claude'
