insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A reabilitação será requerida ao juiz da condenação, após o decurso de quatro ou oito anos, pelo menos, conforme se trate de condenado ou reincidente, contados do dia em que houver terminado a execução da pena principal ou da medida de segurança detentiva, devendo o requerente indicar as comarcas em que haja residido durante esse tempo. O dispositivo foi superado pelo prazo de dois anos do Código Penal.', '["Reabilitação requerida ao juiz da condenação.","Prazos do texto: quatro anos (condenado) ou oito anos (reincidente).","Contados do fim da execução da pena principal ou da medida de segurança.","Indicar as comarcas de residência."]'::jsonb, '["Hoje a reabilitação segue o Código Penal (art. 94): prazo de dois anos."]'::jsonb, 'O condenado que terminou a pena pede a reabilitação ao juiz da condenação.', '["Assertiva que aplica hoje o prazo de oito anos para a reabilitação do reincidente erra, à luz do Código Penal."]'::jsonb, '[{"termo":"Reabilitação","significado":"Direito de sigilo dos antecedentes e de recuperar direitos após a pena."}]'::jsonb, '["Art. 94 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-743'
