insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O requerimento de reabilitação será instruído com certidões comprobatórias de não ter o requerente respondido, nem estar respondendo a processo penal, nas comarcas em que houver residido; atestados de autoridades policiais ou outros documentos que comprovem ter residido nas comarcas indicadas e mantido bom comportamento; atestados de bom comportamento fornecidos por pessoas a cujo serviço tenha estado; quaisquer outros documentos que sirvam como prova de sua regeneração; e prova de haver ressarcido o dano causado pelo crime ou persistir a impossibilidade de fazê-lo.', '["Certidões negativas de processos penais.","Atestados de residência e bom comportamento.","Atestados de quem o contratou.","Outras provas de regeneração.","Prova do ressarcimento do dano ou da impossibilidade."]'::jsonb, '["Provas da regeneração e do ressarcimento."]'::jsonb, 'O requerente junta certidões negativas e atestados de bom comportamento.', '["Assertiva que dispensa a prova de ressarcimento do dano ou da impossibilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 743"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-744'
