insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Durante a execução da pena ou durante o tempo em que a ela se furtar o condenado, poderá ser imposta medida de segurança se o juiz ou o tribunal, na sentença, omitir sua decretação nos casos de periculosidade presumida, deixar de aplicá-la ou de excluí-la expressamente, ou declarar os elementos do processo insuficientes e ordenar indagações para verificar a periculosidade; ou se, tendo sido expressamente excluída a periculosidade na sentença, novos fatos demonstrarem ser o condenado perigoso.', '["Medida de segurança durante a execução ou a fuga do condenado.","Sentença omissa nos casos de periculosidade presumida.","Sentença que não aplicou nem excluiu expressamente.","Elementos insuficientes, com indagações sobre a periculosidade.","Novos fatos após exclusão expressa da periculosidade."]'::jsonb, '["Regras do sistema duplo binário, hoje superado pelo sistema vicariante."]'::jsonb, 'Texto histórico, de aplicação rara com o sistema atual.', '["Assertiva que aplica hoje a periculosidade presumida do art. 751 sem considerar a reforma penal erra."]'::jsonb, '[]'::jsonb, '["Art. 752"]'::jsonb, 'under_review', 'claude'
