select u.id, u.content_sha256, 'Ainda depois de transitar em julgado a sentença absolutória, poderá ser imposta a medida de segurança, enquanto não decorrido tempo equivalente ao da sua duração mínima, a indivíduo que a lei presuma perigoso.', '["Após a absolvição definitiva, medida de segurança ao presumidamente perigoso.","Enquanto não decorrido tempo equivalente ao da duração mínima."]'::jsonb, '["Periculosidade presumida: conceito superado."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que aplica hoje a periculosidade presumida para impor medida de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 751"]'::jsonb, 'under_review', 'claude'
