select u.id, u.content_sha256, 'A aplicação da medida de segurança, nos casos previstos nos arts. 751 e 752, competirá ao juiz da execução da pena e, no caso do art. 753, ao juiz da sentença.', '["Arts. 751 e 752: juiz da execução da pena.","Art. 753: juiz da sentença."]'::jsonb, '["Competência conforme o artigo aplicado."]'::jsonb, 'A medida do art. 751 é aplicada pelo juiz da execução da pena.', '["Assertiva que atribui ao juiz da sentença a medida do art. 751 erra: é o juiz da execução."]'::jsonb, '[]'::jsonb, '["Art. 751","Art. 753"]'::jsonb, 'under_review', 'claude'
