insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos casos do art. 751, I, c, e II, e do art. 752, II, o juiz, depois de proceder às diligências que julgar convenientes, ouvirá o Ministério Público e concederá ao condenado o prazo de três dias para alegações, devendo a prova requerida ou reputada necessária ser produzida em prazo determinado. O juiz nomeará defensor ao condenado que o requerer. Se o réu estiver foragido, o juiz procederá às diligências convenientes, concedendo prazo de provas se requerido pelo MP. Findo o prazo de provas, o juiz proferirá a sentença dentro de três dias.', '["Diligências, oitiva do MP e três dias para as alegações do condenado.","Defensor nomeado se requerido.","Foragido: diligências e prazo de provas a pedido do MP.","Sentença em três dias."]'::jsonb, '["Prazos de três dias."]'::jsonb, 'O juiz ouve o MP, concede três dias ao condenado e sentencia em três dias após as provas.', '["Assertiva que fixa em cinco dias o prazo da sentença após as provas erra: são três."]'::jsonb, '[]'::jsonb, '["Art. 751"]'::jsonb, 'under_review', 'claude'
