select u.id, u.content_sha256, 'O trabalho nos estabelecimentos referidos no art. 88, §1º, III, do Código Penal, será educativo e remunerado, de modo que assegure ao internado meios de subsistência quando cessar a internação. O trabalho poderá ser praticado ao ar livre. Nos outros estabelecimentos, o trabalho dependerá das condições pessoais do internado.', '["Trabalho educativo e remunerado nesses estabelecimentos.","Pode ser ao ar livre.","Nos demais estabelecimentos, depende das condições pessoais do internado."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O internado trabalha, com remuneração, para ter meios de subsistência ao sair.', '["Assertiva que torna gratuito o trabalho do internado erra: é remunerado."]'::jsonb, '[]'::jsonb, '["Art. 765"]'::jsonb, 'under_review', 'claude'
