insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz fixará as normas de conduta que serão observadas durante a liberdade vigiada. São obrigatórias: tomar ocupação, dentro de prazo razoável, se apto para o trabalho, e não mudar do território da jurisdição do juiz sem prévia autorização. Poderão ser impostas, entre outras, não mudar de habitação sem aviso prévio, recolher-se cedo à habitação, não trazer consigo armas ofensivas e não frequentar casas de bebidas ou de tavolagem, nem certas reuniões, espetáculos ou diversões. Será entregue ao indivíduo uma caderneta, de que constarão as obrigações impostas.', '["Normas de conduta fixadas pelo juiz.","Obrigatórias: ocupação lícita e não mudar de jurisdição sem autorização.","Facultativas: aviso de mudança, recolhimento, sem armas, sem certos locais.","Caderneta com as obrigações."]'::jsonb, '["Liberdade vigiada: medida de segurança histórica."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que dispensa a caderneta de obrigações da liberdade vigiada erra."]'::jsonb, '[]'::jsonb, '["Art. 698"]'::jsonb, 'under_review', 'claude'
