insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Mediante representação da autoridade incumbida da vigilância, a requerimento do Ministério Público ou de ofício, poderá o juiz modificar as normas fixadas ou estabelecer outras.', '["Juiz pode modificar as normas ou criar outras.","Por representação da autoridade, a pedido do MP ou de ofício."]'::jsonb, '["Modificação das condições."]'::jsonb, 'O juiz altera as normas de conduta por representação da autoridade que fiscaliza.', '["Assertiva que torna imutáveis as normas fixadas na sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 767"]'::jsonb, 'under_review', 'claude'
