insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para execução do exílio local, o juiz comunicará sua decisão à autoridade policial do lugar ou dos lugares onde o exilado está proibido de permanecer ou de residir. O infrator da medida será conduzido à presença do juiz, que poderá mantê-lo detido até proferir decisão. Reconhecida a transgressão e imposta a liberdade vigiada, o juiz determinará que a autoridade policial providencie para que o infrator siga imediatamente para o lugar de residência por ele escolhido, oficiando à autoridade policial desse lugar.', '["Exílio local comunicado à autoridade policial dos lugares proibidos.","Infrator conduzido ao juiz, que pode mantê-lo detido até decidir.","Transgressão reconhecida: liberdade vigiada e remoção ao lugar de residência escolhido."]'::jsonb, '["Medida histórica, sem aplicação atual."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que aplica hoje o exílio local como medida de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 772"]'::jsonb, 'under_review', 'claude'
