select u.id, u.content_sha256, 'A medida de fechamento de estabelecimento ou de interdição de associação será comunicada pelo juiz à autoridade policial, para que a execute.', '["Fechamento de estabelecimento ou interdição de associação comunicados à autoridade policial.","A polícia executa."]'::jsonb, '["Medida histórica."]'::jsonb, 'O juiz determina o fechamento de um estabelecimento, e a polícia o executa.', '["Assertiva que atribui ao próprio juiz a execução material do fechamento erra: cabe à polícia."]'::jsonb, '[]'::jsonb, '["Art. 772"]'::jsonb, 'under_review', 'claude'
