select u.id, u.content_sha256, 'Nos casos do parágrafo único do art. 83 do Código Penal, ou quando a transgressão de uma medida de segurança importar a imposição de outra, observar-se-á o disposto no art. 757, no que for aplicável.', '["Transgressão que leva a outra medida de segurança: aplica-se, no que couber, o art. 757."]'::jsonb, '["Remissão ao art. 757."]'::jsonb, 'Texto histórico, sem aplicação prática atual.', '["Assertiva que cria rito próprio para a transgressão da medida erra: aplica-se o art. 757."]'::jsonb, '[]'::jsonb, '["Art. 757"]'::jsonb, 'under_review', 'claude'
