insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cessação ou não da periculosidade se verificará ao fim do prazo mínimo de duração da medida de segurança pelo exame das condições da pessoa a que tiver sido imposta, observando-se que o diretor do estabelecimento de internação ou a autoridade policial remeterá ao juiz da execução minucioso relatório, até um mês antes de expirado o prazo mínimo se não for inferior a um ano, ou até quinze dias nos outros casos; que, se o indivíduo estiver internado em manicômio judiciário ou casa de custódia, o relatório será acompanhado do laudo de exame pericial feito por dois médicos designados pelo diretor; e que o diretor ou a autoridade deverá concluir pela conveniência da revogação ou não da medida.', '["Verificação da periculosidade ao fim do prazo mínimo.","Relatório até um mês antes (prazo mínimo igual ou superior a um ano) ou quinze dias nos demais casos.","Internado: laudo de dois médicos.","Conclusão sobre a revogação ou não da medida."]'::jsonb, '["Um mês ou quinze dias de antecedência para o relatório."]'::jsonb, 'O diretor envia o relatório e o laudo de dois médicos antes do fim do prazo mínimo.', '["Assertiva que dispensa o laudo médico do internado no relatório do diretor erra."]'::jsonb, '[]'::jsonb, '["Art. 776","Art. 777"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-775'
