insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos exames sucessivos a que se referem o §1º, II, e §2º do art. 81 do Código Penal, observar-se-á, no que lhes for aplicável, o disposto no artigo anterior.', '["Exames sucessivos seguem, no que couber, o art. 775."]'::jsonb, '["Remissão ao art. 775."]'::jsonb, 'Os exames periódicos seguem o procedimento do art. 775.', '["Assertiva que cria rito próprio para os exames sucessivos erra."]'::jsonb, '[]'::jsonb, '["Art. 775"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-776'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer tempo, ainda durante o prazo mínimo de duração da medida de segurança, poderá o tribunal, câmara ou turma, a requerimento do Ministério Público ou do interessado, seu defensor ou curador, ordenar o exame para a verificação da cessação da periculosidade. Designado o relator e ouvido o procurador-geral, se a medida não tiver sido por ele requerida, o pedido será julgado na primeira sessão. Deferido o pedido, a decisão será imediatamente comunicada ao juiz, que requisitará, marcando prazo, o relatório e o exame ou ordenará as diligências.', '["A qualquer tempo, o tribunal pode ordenar o exame de cessação da periculosidade.","Requerimento do MP, do interessado, do defensor ou do curador.","Julgamento na primeira sessão.","Deferido, o juiz requisita o relatório e o exame."]'::jsonb, '["Exame possível mesmo antes do prazo mínimo."]'::jsonb, 'O defensor pede ao tribunal o exame de cessação da periculosidade antes do prazo mínimo.', '["Assertiva que exige o fim do prazo mínimo para pedir o exame de cessação da periculosidade erra."]'::jsonb, '[]'::jsonb, '["Art. 775"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-777'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitando em julgado a sentença de revogação, o juiz expedirá ordem para a desinternação, quando se tratar de medida detentiva, ou para que cesse a vigilância ou a proibição, nos outros casos.', '["Revogação da medida transitada em julgado: ordem de desinternação.","Nas demais medidas: cessa a vigilância ou a proibição."]'::jsonb, '["Efeito da revogação."]'::jsonb, 'Revogada definitivamente a medida, o juiz expede a ordem de desinternação.', '["Assertiva que mantém a internação após o trânsito da revogação erra."]'::jsonb, '[]'::jsonb, '["Art. 775"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-778'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

